var t = new Thread(() =>
    Thread.Sleep(200));
Console.WriteLine(t.ThreadState);
// Unstarted
t.Start();
Thread.Sleep(50);
Console.WriteLine(t.ThreadState);
// WaitSleepJoin (schläft gerade)
t.Join();
Console.WriteLine(t.ThreadState);
// Stopped
Console.WriteLine(t.IsAlive);
// False

var t = new Thread(() =>
    Thread.Sleep(500));
t.Start();
Console.WriteLine(t.Join(100));
// False (noch nicht fertig)
Console.WriteLine(t.Join(1000));
// True

t.Start(); // ThreadStateException

var cts =
    new CancellationTokenSource();
var token = cts.Token;
var t = new Thread(() =>
{
    while (!token
        .IsCancellationRequested)
    {
        // Arbeit erledigen ...
        Thread.Sleep(100);
    }
    Console.WriteLine("Sauber beendet");
});
t.Start();
Thread.Sleep(350);
cts.Cancel();  // um Ende bitten
t.Join();
Console.WriteLine(t.ThreadState);
// Stopped

